[1287]={["aftermath"]="Vimes planned to send Caldwell against the deserters and to continue the search for Reethe.",["atomIDs"]={"1287:description:1-7","1287:description:9-20","1287:description:25-132","1287:description:134-209","1287:description:214-288","1287:description:293-316","1287:description:318-377","1287:objective:1-58"},["endingAtomIDs"]={"1287:completion:1-73","1287:completion:75-122","1287:completion:124-198"},["opening"]="Balos said the deserters expelled Reethe for raiding Brackenwall supplies. Fear of provoking the ogres was his explanation for abandoning their former companion.",["pending"]="{actor} meant to report Balos's account to Vimes.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} carried the deserter's information to Vimes.",["sourceHash"]="e8e89c8fd297f7bd7368f007387027efc46d8b1913c55d1180f65ecb461dd8a2",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[1301]={["atomIDs"]={"1301:description:1-108","1301:description:110-133","1301:description:135-204","1301:description:209-232","1301:description:234-343","1301:description:348-438","1301:objective:1-43"},["opening"]="Connor credited James Hyal with the skills and opportunities behind his life at the Blue Recluse. With no recent news of his old teacher, he suggested a greeting through James's brother Vincent in Menethil.",["pending"]="{actor} planned to speak with Vincent Hyal in Menethil.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Vincent Hyal in Menethil Harbor.",["sourceClassMask"]="?",["sourceHash"]="0aa6a3e918ceaad7fb691c7649d758c6fa177a67093e80756fbbc9cb3a65b63a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
