[1319]={["aftermath"]="Caz excluded his own work and that of the smiths he knew on this side of the sea.",["atomIDs"]={"1319:description:1-83","1319:description:85-160","1319:description:165-217","1319:objective:1-63"},["endingAtomIDs"]={"1319:completion:7-46","1319:completion:48-161"},["opening"]="Vimes turned the shield inquiry over to a craftsman. Caz worked Theramore's forge and might recognize details a soldier would miss.",["pending"]="{actor} meant to show the damaged shield to Caz.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the shield to the smithy.",["sourceHash"]="5aa502ec268377ed83d2cdfff66ae3c9b970a4dc04105d7cbacbadd4096fcedc",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[1320]={["aftermath"]="Vimes retained the clue while acknowledging that it offered little to work with.",["atomIDs"]={"1320:description:1-27","1320:description:29-132","1320:description:134-162","1320:description:167-198","1320:description:200-255","1320:objective:1-45"},["endingAtomIDs"]={"1320:completion:1-74","1320:completion:76-198"},["opening"]="Caz noticed traces of a burned leather strap sized for a large bearer. He guessed a tauren and asked that his limited finding reach Vimes.",["pending"]="{actor} meant to relay Caz's assessment.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the smith's observations to Vimes.",["sourceHash"]="8839aac8dd7f0dfdd0b9a172d2c3e4af3f9437fe61779930901ddd4b3802b909",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[1321]={["atomIDs"]={"1321:description:1-6","1321:description:8-65","1321:description:67-196","1321:objective:1-64"},["opening"]="Krog could not identify anything unusual in the shield. Its construction might reveal more to Do'gol, Brackenwall's smith.",["pending"]="{actor} planned to ask Do'gol to examine the shield.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} showed the shield to Do'gol.",["sourceHash"]="cbd1ae0572f7b302615ce16dbcef2dc90c158af0f4ae4f23809698a4e5d6d666",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
