[1505]={["atomIDs"]={"1505:description:1-69","1505:description:72-127","1505:description:132-146","1505:description:149-235","1505:description:238-338","1505:objective:1-35"},["opening"]="Krang praised strength but considered the greatest warriors students as well. Uzzek's experience now served instruction at Far Watch Post, making the veteran the next teacher to meet.",["pending"]="{actor} planned to seek Uzzek at Far Watch Post.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Uzzek at Far Watch Post.",["sourceClassMask"]="1",["sourceHash"]="1428edd643eee59c27f646462c7bfe832dd75ec8a09d9038de05d22b3f2035b6",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
